create table if not exists holdout_v2.failure_analysis (
  result_id integer not null references holdout_v2.result_of_record(result_id),
  case_key text not null references holdout_v2.case_v2(case_key),
  bucket text not null,
  root_causes text not null,
  classifications text not null,
  per_language jsonb not null,
  parity boolean not null,
  analysed_at timestamptz not null default now(),
  primary key (result_id, case_key)
);
alter table holdout_v2.failure_analysis enable row level security;
create table if not exists holdout_v2.root_cause (
  code text primary key, description text not null, classification text not null
);
alter table holdout_v2.root_cause enable row level security;
on conflict (code) do nothing;
on conflict do nothing;
